function previewJobForm(form:HTMLFormElement|null){if(!form)return;const data=new FormData(form),read=(key:string)=>String(data.get(key)||'').trim(),escape=(value:string)=>value.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));const title=read('title')||'Untitled opportunity',details=[['Department',read('department')],['Category',read('job_category')],['Type',read('kind')],['Work mode',read('work_mode')],['Location',[read('city'),read('state'),read('country')].filter(Boolean).join(', ')||read('location')],['Compensation',read('compensation')],['Application deadline',read('application_deadline')]].filter(([,value])=>value).map(([label,value])=>`<p><b>${escape(label)}:</b> ${escape(value)}</p>`).join('');const popup=window.open('','_blank','width=760,height=820');if(!popup){alert('Allow pop-ups to open the job preview.');return;}popup.document.open();popup.document.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(title)} · Preview</title><style>body{margin:0;background:#eef3f8;color:#183047;font:16px Arial,sans-serif}.preview{max-width:760px;margin:48px auto;padding:36px;background:white;border-radius:18px;box-shadow:0 12px 40px #1232}small{color:#4868bd;text-transform:uppercase;letter-spacing:.12em}h1{font-size:40px}p{line-height:1.7;color:#465c70}.tag{display:inline-block;padding:7px 11px;border-radius:30px;background:#eef2ff;color:#354d91}</style></head><body><main class="preview"><small>RILORA opportunity preview · Not yet published</small><h1>${escape(title)}</h1><span class="tag">${escape(read('kind')||'Opportunity')}</span><p>${escape(read('description')||'Add a job overview to complete this preview.')}</p>${details}<h2>Responsibilities</h2><p>${escape(read('responsibilities')||'Not specified')}</p><h2>Requirements</h2><p>${escape(read('requirements')||'Not specified')}</p></main></body></html>`);popup.document.close()}function JobImageField(){const [preview,setPreview]=useState('');useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview]);return <div className="field"><label htmlFor="job_image_file">Upload a job card image (JPEG, PNG or WebP; max 5 MB)</label><input id="job_image_file" name="job_image_file" type="file" accept="image/jpeg,image/png,image/webp" onChange={e=>{if(preview)URL.revokeObjectURL(preview);const file=e.target.files?.[0];setPreview(file?URL.createObjectURL(file):'')}}/>{preview&&<img src={preview} alt="Job image preview" className="job-image-preview"/>}</div>}function Input({label,name,type='text',required=false,placeholder=''}:{label:string,name:string,type?:string,required?:boolean,placeholder?:string}){return <div className="field"><label>{label}{required?' *':''}</label><input name={name} type={type} required={required} placeholder={placeholder}/></div>}
function Text({label,name,required=false}:{label:string,name:string,required?:boolean}){return <div className="field span2"><label>{label}{required?' *':''}</label><textarea name={name} required={required}/></div>}
function AdminDashboardSidebar({active,onSelect,onLogout,unread=0}:{active:string,onSelect:(tab:string)=>void,onLogout:()=>Promise<void>,unread?:number}){const tabs=[['overview','Overview'],['applications','Applications'],['opportunities','Job Management'],['enquiries','Enquiries'],['email_management','Email Management'],['content','Website Content'],['website_analytics','Website Analytics'],['partnership_management','Partnership Management'],['settings','Settings']];const tools=[['projects','Projects'],['assignments','Contributor Allocation'],['services','Services'],['partnerships','Published Partnerships'],['career_interests','Career Interests'],['certificates','Certificates']];return <aside className="dashnav">{tabs.map(([key,label])=><button type="button" key={key} className={active===key?'active':''} aria-current={active===key?'page':undefined} onClick={()=>onSelect(key)}>{label}{key==='enquiries'&&unread>0?` (${unread})`:''}</button>)}<details className="dash-tools"><summary>More tools</summary>{tools.map(([key,label])=><button type="button" key={key} className={active===key?'active':''} aria-current={active===key?'page':undefined} onClick={()=>onSelect(key)}>{label}</button>)}</details><button type="button" onClick={()=>void onLogout()}>Log out</button></aside>}
function Table({rows,columns,render,actions}:{rows:Item[],columns:string[],render?:(row:Item,key:string)=>any,actions?:(row:Item)=>any}){const [page,setPage]=useState(1),pageSize=10,totalPages=Math.max(1,Math.ceil(rows.length/pageSize)),currentPage=Math.min(page,totalPages),visibleRows=rows.slice((currentPage-1)*pageSize,currentPage*pageSize);useEffect(()=>setPage(1),[rows]);return <div className="tablewrap"><table className="table"><thead><tr>{columns.map(c=><th key={c}>{c.replaceAll('.',' ').replaceAll('_',' ')}</th>)}{actions&&<th>Actions</th>}</tr></thead><tbody>{visibleRows.map(r=><tr key={r.id}>{columns.map(c=>{const value:any=c.split('.').reduce((v:any,x:string)=>v?.[x],r);return <td key={c}>{render?render(r,c):value===true?'Yes':value===false?'No':String(value??'—')}</td>})}{actions&&<td>{actions(r)}</td>}</tr>)}</tbody></table>{!rows.length&&<div className="empty">No records yet.</div>}{totalPages>1&&<div className="admin-table-pagination"><span>Showing {(currentPage-1)*pageSize+1}–{Math.min(currentPage*pageSize,rows.length)} of {rows.length}</span><button type="button" className="btn small secondary" onClick={()=>setPage(currentPage-1)} disabled={currentPage===1}>Previous</button><span>Page {currentPage} of {totalPages}</span><button type="button" className="btn small secondary" onClick={()=>setPage(currentPage+1)} disabled={currentPage===totalPages}>Next</button></div>}</div>}
type AnalyticsData={totalVisits:number;uniqueVisitors:number;totalPageViews:number;rangeVisits:number;rangeUniqueVisitors:number;rangePageViews:number;todayVisitors:number;todayVisits:number;yesterdayVisitors:number;yesterdayVisits:number;last7DaysVisits:number;last7DaysVisitors:number;last30DaysVisits:number;last30DaysVisitors:number;monthlyVisitors:number;daily:Array<{date:string;pageViews:number;visits:number;uniqueVisitors:number}>;popularPages:Array<{path:string;pageViews:number}>;recentActivity:Array<{path:string;visitedAt:string}>};
function localDate(value:Date){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(value)}
function AnalyticsManager({token}:{token:string}){
  const today=localDate(new Date()),defaultFrom=(()=>{const date=new Date(`${today}T00:00:00Z`);date.setUTCDate(date.getUTCDate()-29);return date.toISOString().slice(0,10)})();
  const [from,setFrom]=useState(defaultFrom),[to,setTo]=useState(today),[data,setData]=useState<AnalyticsData|null>(null),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
  useEffect(()=>{let active=true;setBusy(true);setMessage('');fetch(`/api/admin/analytics?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`,{headers:{Authorization:`Bearer ${token}`}}).then(async response=>{const payload=await response.json();if(!response.ok)throw new Error(payload.error||'Analytics could not be loaded.');if(active)setData(payload.data as AnalyticsData)}).catch(error=>{if(active){setData(null);setMessage(error instanceof Error?error.message:'Analytics are unavailable.')}}).finally(()=>{if(active)setBusy(false)});return()=>{active=false}},[from,to,token]);
  const cards=data?[['Total Visits',data.totalVisits,'Distinct anonymous browser sessions, all time'],['Unique Visitors',data.uniqueVisitors,'Distinct anonymous visitor IDs, all time'],["Today's Visitors",data.todayVisitors,'Distinct visitors today (IST)'],['Monthly Visitors',data.monthlyVisitors,'Distinct visitors this calendar month'],['Total Page Views',data.totalPageViews,'Recorded public page views, all time']]:[];
  const daily=data?.daily||[],maxValue=Math.max(1,...daily.map(day=>Math.max(day.pageViews,day.visits,day.uniqueVisitors)));
  const line=(field:'pageViews'|'visits'|'uniqueVisitors')=>daily.map((day,index)=>`${daily.length<2?0:20+index*720/(daily.length-1)},${188-day[field]/maxValue*160}`).join(' ');
  return <div className="analytics-manager">
    <div className="card analytics-range"><div className="field"><label htmlFor="analytics-from">From (IST)</label><input id="analytics-from" type="date" value={from} max={to} onChange={event=>setFrom(event.target.value)}/></div><div className="field"><label htmlFor="analytics-to">To (IST)</label><input id="analytics-to" type="date" value={to} min={from} max={today} onChange={event=>setTo(event.target.value)}/></div><p className="status">Selected range: {data?.rangeVisits??'—'} visits · {data?.rangeUniqueVisitors??'—'} unique visitors · {data?.rangePageViews??'—'} page views</p></div>
    {message&&<div className="notice" role="status">{message}</div>}{busy&&!data&&<div className="empty">Loading real visitor analytics…</div>}
    {data&&<><div className="grid analytics-stat-grid">{cards.map(([label,value,description])=><article className="card analytics-stat" key={String(label)}><span>{label}</span><strong>{Number(value).toLocaleString()}</strong><small>{description}</small></article>)}</div>
      <div className="grid two" style={{marginTop:18}}><section className="card analytics-trend"><h2>Visitors and page views over time</h2><p className="status">Daily trends in the selected range. Visits count sessions; unique visitors count distinct anonymous IDs; page views count individual public pages.</p>
        {daily.length?<div className="analytics-chart-wrap"><svg viewBox="0 0 760 220" role="img" aria-label="Daily visits, unique visitors and page views" preserveAspectRatio="none"><line x1="20" y1="190" x2="740" y2="190"/><line x1="20" y1="108" x2="740" y2="108"/><line x1="20" y1="28" x2="740" y2="28"/><polyline className="analytics-line-pageviews" points={line('pageViews')}/><polyline className="analytics-line-visits" points={line('visits')}/><polyline className="analytics-line-unique" points={line('uniqueVisitors')}/></svg><div className="analytics-chart-labels"><span>{daily[0]?.date}</span><span>{daily[Math.floor(daily.length/2)]?.date}</span><span>{daily[daily.length-1]?.date}</span></div><div className="analytics-legend"><span className="analytics-legend-pageviews">Page views</span><span className="analytics-legend-visits">Visits</span><span className="analytics-legend-unique">Unique visitors</span></div></div>:<div className="empty">No recorded views in this date range.</div>}
        <div className="analytics-periods"><span>Today: {data.todayVisits} visits / {data.todayVisitors} visitors</span><span>Yesterday: {data.yesterdayVisits} visits / {data.yesterdayVisitors} visitors</span><span>Last 7 days: {data.last7DaysVisits} visits / {data.last7DaysVisitors} visitors</span><span>Last 30 days: {data.last30DaysVisits} visits / {data.last30DaysVisitors} visitors</span></div>
      </section><section className="card"><h2>Most visited pages</h2><Table rows={data.popularPages} columns={['path','pageViews']}/></section></div>
      <section className="card" style={{marginTop:18}}><h2>Recent page activity</h2><p className="status">Only page path and timestamp are stored. Visitor and session identifiers are never returned.</p><Table rows={data.recentActivity.map((item,index)=>({...item,id:`activity-${index}`}))} columns={['path','visitedAt']}/></section></>}
  </div>;
}type PartnershipEnquiry=Item&{partnership_id:string;organisation:string;partnership_status:string;service_required:string;project_description:string};
function PartnershipEnquiryManager({token}:{token:string}){const [rows,setRows]=useState<PartnershipEnquiry[]>([]),[query,setQuery]=useState(''),[status,setStatus]=useState('all'),[message,setMessage]=useState('');async function load(){try{const response=await fetch('/api/admin/partnership-enquiries',{headers:{Authorization:`Bearer ${token}`}}),result=await response.json();if(!response.ok)throw new Error(result.error||'Could not load partnership enquiries.');setRows(result.data||[]);setMessage('')}catch(error){setMessage(error instanceof Error?error.message:'Could not load partnership enquiries.')}}useEffect(()=>{void load()},[token]);async function update(row:PartnershipEnquiry,nextStatus:string,internal_notes?:string){if(['approved','active'].includes(nextStatus)&&!window.confirm(`Set ${row.partnership_id} to ${nextStatus}? This publishes the organization as an approved RILORA partnership and updates the public count.`))return;const response=await fetch('/api/admin/partnership-enquiries',{method:'PATCH',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id:row.id,status:nextStatus,internal_notes})}),result=await response.json();setMessage(response.ok?`Partnership ${row.partnership_id} updated to ${nextStatus}.`:result.error||'Could not update partnership.');if(response.ok)await load()}const shown=rows.filter(row=>(status==='all'||row.partnership_status===status)&&(!query||`${row.partnership_id} ${row.organisation} ${row.name} ${row.email} ${row.service_required}`.toLowerCase().includes(query.toLowerCase())));const count=(key:string)=>rows.filter(row=>row.partnership_status===key).length;return <div className="partnership-admin"><div className="grid partnership-stat-grid">{[['Total enquiries',rows.length],['Pending',count('pending')],['Under review',count('under_review')],['Approved',count('approved')],['Active',count('active')],['Rejected',count('rejected')]].map(([label,value])=><article className="card" key={String(label)}><span>{label}</span><strong>{Number(value).toLocaleString()}</strong></article>)}</div><div className="card" style={{marginTop:18}}><h2>Partnership enquiries</h2><p className="status">Only partnership-category submissions appear here. Approved and active records become public partner entries; contact details remain private.</p><div className="filters"><input className="career-search" aria-label="Search partnership enquiries" placeholder="Search organization, contact, email or partnership ID" value={query} onChange={event=>setQuery(event.target.value)}/><select aria-label="Filter partnership status" value={status} onChange={event=>setStatus(event.target.value)}><option value="all">All statuses</option>{['pending','under_review','approved','active','rejected'].map(value=><option key={value} value={value}>{value.replace('_',' ')}</option>)}</select></div>{message&&<p className="notice" role="status">{message}</p>}<Table rows={shown} columns={['partnership_id','organisation','name','email','service_required','partnership_status','created_at']} actions={row=><><button type="button" className="btn small secondary" onClick={()=>window.alert([`Partnership ID: ${row.partnership_id}`,`Organization: ${row.organisation}`,`Contact: ${row.name}`,`Email: ${row.email}`,`Phone: ${row.phone||'—'}`,`Type: ${row.service_required}`,`Details: ${row.project_description}`,`Internal notes: ${row.internal_notes||'—'}`].join('\n'))}>View details</button><button type="button" className="btn small secondary" onClick={()=>{const note=window.prompt('Private administrator notes',row.internal_notes||'');if(note!==null)void update(row as PartnershipEnquiry,row.partnership_status,note)}}>Notes</button><select aria-label={`Status for ${row.partnership_id}`} value={row.partnership_status} onChange={event=>void update(row as PartnershipEnquiry,event.target.value)}>{['pending','under_review','approved','active','rejected'].map(value=><option key={value} value={value}>{value.replace('_',' ')}</option>)}</select></>}/></div></div>}
function CareerInterestManager({token}:{token:string}){const [rows,setRows]=useState<Item[]>([]),[message,setMessage]=useState('');async function load(){const r=await fetch('/api/admin/career-interests',{headers:{Authorization:`Bearer ${token}`}}),d=await r.json();setRows(d.data||[]);if(!r.ok)setMessage(d.error||'Could not load role interests.');}useEffect(()=>{void load();},[]);async function update(id:string,status:string){const r=await fetch('/api/admin/career-interests',{method:'PATCH',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id,status})}),d=await r.json();setMessage(r.ok?'Submission status updated.':d.error||'Could not update submission.');if(r.ok)void load();}async function download(id:string){const r=await fetch('/api/admin/career-interests',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id})}),d=await r.json();if(!r.ok){setMessage(d.error||'Could not prepare resume.');return;}window.open(d.url,'_blank','noopener,noreferrer');}return <section className="card"><p className="status">Role interests are expressions of interest, not job offers or active vacancies. Applicant data is visible only to administrators.</p>{message&&<div className="notice" role="status">{message}</div>}<Table rows={rows} columns={['full_name','email','role_title','created_at','status']} actions={r=><><button className="btn small secondary" onClick={()=>download(r.id)}>Download resume</button><select aria-label={`Status for ${r.full_name}`} value={r.status} onChange={e=>update(r.id,e.target.value)}>{['new','reviewed','contacted','closed'].map(s=><option key={s} value={s}>{s}</option>)}</select></>}/></section>}
type ManualEmailType='general'|'shortlist'|'interview'|'selection'|'rejection';
function ApplicationEmailComposer({row,token}:{row:Item,token:string}){
 const initial:ManualEmailType=row.status==='selected'?'selection':row.status==='rejected'?'rejection':row.status==='interview'?'interview':row.status==='shortlisted'?'shortlist':'general';
 const [type,setType]=useState<ManualEmailType>(initial),[subject,setSubject]=useState(''),[message,setMessage]=useState(''),[recipient,setRecipient]=useState(String(row.email||'')),[open,setOpen]=useState(false),[busy,setBusy]=useState(false),[notice,setNotice]=useState('');
 const name=row.profiles?.full_name||row.applicant_full_name||'Candidate',job=row.opportunities?.title||'RILORA opportunity';
 function draft(next:ManualEmailType){const content:Record<ManualEmailType,{subject:string,message:string}>={general:{subject:`RILORA – Update About Your ${job} Application`,message:`Hello ${name},\n\nI am contacting you regarding your application for ${job}.\n\nRegards,\nRILORA Recruitment Team`},shortlist:{subject:`RILORA – You Have Been Shortlisted for ${job}`,message:`We are pleased to let you know that your application for ${job} has been shortlisted. Our team will share the next steps with you soon.`},interview:{subject:`RILORA – Interview Details for ${job}`,message:`We would like to invite you to an interview for ${job}. Our team will contact you with the schedule and meeting details.`},selection:{subject:'Congratulations! You Have Been Selected – RILORA',message:`Congratulations!\n\nWe are pleased to inform you that you have been selected for the position of ${job} at RILORA.\n\nFurther details regarding next steps will be communicated to you separately.\n\nRegards,\nRILORA Recruitment Team`},rejection:{subject:`RILORA – Update on Your ${job} Application`,message:`Thank you for applying for ${job} at RILORA. After careful consideration, we will not be moving forward with your application at this time. We appreciate your interest and wish you the best.`}};setType(next);setSubject(content[next].subject);setMessage(content[next].message);setNotice('');setOpen(true)}
 async function submit(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!window.confirm(`Send this email to ${recipient||'the candidate'}?`))return;setBusy(true);setNotice('');try{const response=await fetch('/api/admin/application-email',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({application_id:row.id,email_type:type,recipient,subject,message})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Email could not be sent.');if(data.sent){setNotice('Email provider confirmed the message and it was recorded.');setOpen(false)}else setNotice(data.configured?'The email provider did not confirm delivery. The result was recorded.':'Email delivery is not configured. No message was sent.')}catch(error){setNotice(error instanceof Error?error.message:'Email could not be sent.')}finally{setBusy(false)}}
 return <><div className="application-email-actions"><button className="btn small secondary" onClick={()=>draft('general')}>Contact candidate</button>{row.status==='shortlisted'&&<button className="btn small secondary" onClick={()=>draft('shortlist')}>Shortlist email</button>}{row.status==='interview'&&<button className="btn small secondary" onClick={()=>draft('interview')}>Interview email</button>}{row.status==='selected'&&<button className="btn small secondary" onClick={()=>draft('selection')}>Selection email</button>}{row.status==='rejected'&&<button className="btn small secondary" onClick={()=>draft('rejection')}>Rejection email</button>}</div>{notice&&<p className="status" role="status">{notice}</p>}{open&&<div className="email-composer-backdrop"><section className="email-composer card" role="dialog" aria-modal="true" aria-labelledby={`email-title-${row.id}`}><h2 id={`email-title-${row.id}`}>Compose candidate email</h2><p className="status">Candidate: {name} · Position: {job} · Application: {row.id}</p><form onSubmit={submit}><div className="field"><label>Email template</label><select value={type} onChange={event=>draft(event.target.value as ManualEmailType)}><option value="general">General communication</option><option value="shortlist">Shortlisting</option><option value="interview">Interview scheduling</option><option value="selection">Selection</option><option value="rejection">Rejection</option></select></div><div className="field"><label>Recipient</label><input type="email" value={recipient} onChange={event=>setRecipient(event.target.value)} maxLength={254} required/></div><div className="field"><label>Subject</label><input value={subject} onChange={event=>setSubject(event.target.value)} maxLength={200} required/></div><div className="field"><label>Email message</label><textarea value={message} onChange={event=>setMessage(event.target.value)} maxLength={5000} rows={8} required/></div><div className="email-preview"><h3>Preview</h3><p>To: {recipient}</p><p>{message}</p><p>Application reference: {row.id}<br/>RILORA Recruitment Team</p></div><div className="heroactions"><button className="btn" disabled={busy}>{busy?'Sending…':'Review and send'}</button><button type="button" className="btn secondary" onClick={()=>setOpen(false)} disabled={busy}>Cancel</button></div></form></section></div>}</>
}function EmailManagement({token}:{token:string}){const [rows,setRows]=useState<Item[]>([]),[configured,setConfigured]=useState(false),[serverConfigured,setServerConfigured]=useState(false),[totals,setTotals]=useState({sent:0,failed:0}),[adminEmail,setAdminEmail]=useState('rilora.official@gmail.com'),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);async function load(){const response=await fetch('/api/admin/email',{headers:{Authorization:`Bearer ${token}`}}),data=await response.json();if(!response.ok){setMessage(data.error||'Could not load email history.');return;}setRows(data.data||[]);setConfigured(Boolean(data.configured));setServerConfigured(Boolean(data.serverStorageConfigured));setTotals(data.totals||{sent:0,failed:0});setAdminEmail(data.adminEmail||'rilora.official@gmail.com');}useEffect(()=>{void load();},[]);async function test(){if(!window.confirm(`Send a test email to ${adminEmail}?`))return;setBusy(true);setMessage('');try{const response=await fetch('/api/admin/email',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({action:'test'})}),data=await response.json();if(!response.ok)throw new Error(data.error||'Email test failed.');setMessage('Test email sent.');await load();}catch(error){setMessage(error instanceof Error?error.message:'Email test failed.');}finally{setBusy(false);}}return <div className="grid"><section className="card"><h2>Email provider status</h2><p>Provider credentials: <strong>{configured?'Configured':'Not configured'}</strong></p><p>Secure email history storage: <strong>{serverConfigured?'Connected':'Requires Supabase service role key'}</strong></p><p>Administrator notification inbox: <strong className="email-highlight">{adminEmail}</strong></p><p className="status">Secrets are never displayed in this dashboard.</p><button className="btn" onClick={test} disabled={busy||!configured}>{busy?'Sending…':'Send test email'}</button>{message&&<p className="notice" role="status">{message}</p>}</section><section className="card"><h2>Email delivery history</h2><p>Total emails sent: {totals.sent} · Failed attempts: {totals.failed} · Recent history shown: {rows.length}</p><Table rows={rows} columns={['created_at','email_type','recipient_email','subject','delivery_status','application_id']}/></section></div>}
function ContentManager({token}:{token:string}){
 const [rows,setRows]=useState<Item[]>([]),[key,setKey]=useState(''),[value,setValue]=useState(''),[publishNew,setPublishNew]=useState(false),[message,setMessage]=useState('');
 async function load(){const response=await fetch('/api/content',{headers:{Authorization:`Bearer ${token}`}}),data=await response.json();if(response.ok)setRows(data.records||[]);else setMessage(data.error||'Could not load website content.')}
 useEffect(()=>{void load()},[]);
 async function save(content_key:string,content_value:string,is_public:boolean){const response=await fetch('/api/content',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({content_key,content_value,is_public})}),data=await response.json();setMessage(response.ok?'Website content saved.':data.error||'Unable to save content.');if(response.ok)void load()}
 return <div className="card"><h2>Website copy</h2><p className="status">Publish approved public copy to the website and RiloraGPT. Keep private or draft copy unpublished.</p><div className="grid two">{rows.map(row=><div className="field" key={row.content_key}><label htmlFor={`copy-${row.content_key}`}>{row.content_key}</label><textarea id={`copy-${row.content_key}`} defaultValue={row.content_value} maxLength={5000}/><label className="field-inline"><input type="checkbox" defaultChecked={row.is_public} onChange={event=>{row.is_public=event.target.checked}}/> Public on website and RiloraGPT</label><button className="btn small" onClick={()=>{const text=document.getElementById(`copy-${row.content_key}`) as HTMLTextAreaElement|null;if(text)void save(row.content_key,text.value,Boolean(row.is_public))}}>Save copy</button></div>)}</div><h3>Add website copy</h3><div className="field"><label htmlFor="new-content-key">Key</label><input id="new-content-key" value={key} onChange={e=>setKey(e.target.value)} placeholder="e.g. about_intro"/></div><div className="field"><label htmlFor="new-content-value">Content</label><textarea id="new-content-value" value={value} onChange={e=>setValue(e.target.value)} maxLength={5000}/></div><label className="field-inline"><input type="checkbox" checked={publishNew} onChange={e=>setPublishNew(e.target.checked)}/> Publish publicly</label><button className="btn" disabled={!key.trim()||!value.trim()} onClick={async()=>{await save(key,value,publishNew);setKey('');setValue('');setPublishNew(false)}}>Save content</button>{message&&<p className="message" role="status">{message}</p>}</div>
}function PartnershipManager({token}:{token:string}){const [rows,setRows]=useState<Item[]>([]),[message,setMessage]=useState('');async function load(){const r=await fetch('/api/admin/partnerships',{headers:{Authorization:`Bearer ${token}`}}),d=await r.json();setRows(d.data||[]);}useEffect(()=>{load();},[]);async function create(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,body:any=Object.fromEntries(new FormData(form));body.is_published=body.is_published==='on';const r=await fetch('/api/admin/partnerships',{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();setMessage(r.ok?'Partnership created.':d.error);if(r.ok){form.reset();load();}}async function toggle(row:Item){const r=await fetch('/api/admin/partnerships',{method:'PATCH',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id:row.id,is_published:!row.is_published})}),d=await r.json();setMessage(r.ok?'Partnership updated.':d.error);load();}async function edit(row:Item){const name=prompt('Organisation name',row.name);if(name===null)return;const description=prompt('Approved description',row.description);if(description===null)return;const logo_url=prompt('Approved logo URL',row.logo_url||'');if(logo_url===null)return;const website_url=prompt('Website URL',row.website_url||'');if(website_url===null)return;const r=await fetch('/api/admin/partnerships',{method:'PATCH',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id:row.id,name,description,logo_url:logo_url||null,website_url:website_url||null})}),d=await r.json();setMessage(r.ok?'Partnership updated.':d.error);load();}async function remove(row:Item){if(!confirm(`Delete ${row.name}?`))return;const r=await fetch('/api/admin/partnerships',{method:'DELETE',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id:row.id})}),d=await r.json();setMessage(r.ok?'Partnership deleted.':d.error);load();}return <><form className="card" onSubmit={create}><h2>Add confirmed partnership</h2><p className="status">Publish only collaborations approved by RILORA. CureTrics is the currently confirmed partner.</p><div className="formgrid"><Input label="Organisation name" name="name" required/><Input label="Logo URL" name="logo_url"/><Input label="Website URL" name="website_url"/><Text label="Approved description" name="description" required/><div className="field"><label><input type="checkbox" name="is_published"/> Publish</label></div></div><button className="btn">Save partnership</button></form><div className="card" style={{marginTop:18}}><h2>Partnership records</h2><Table rows={rows} columns={['name','description','is_published']} actions={r=><><button className="btn small secondary" onClick={()=>toggle(r)}>{r.is_published?'Unpublish':'Publish'}</button><button className="btn small secondary" onClick={()=>edit(r)}>Edit</button><button className="btn small secondary" onClick={()=>remove(r)}>Delete</button></>}/></div>{message&&<div className="notice">{message}</div>}</>}
function OpportunityEditor({row,token,onCancel,onSaved}:{row:Item,token:string,onCancel:()=>void,onSaved:()=>void}){const [message,setMessage]=useState('');async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,formData=new FormData(form),file=formData.get('job_image_file');const f=Object.fromEntries(formData) as any;delete f.job_image_file;let imagePath='';if(file instanceof File&&file.size){const uploadForm=new FormData();uploadForm.set('image',file);const upload=await fetch('/api/admin/job-image',{method:'POST',headers:{Authorization:`Bearer ${token}`},body:uploadForm}),result=await upload.json();if(!upload.ok){setMessage(result.error||'Image upload failed.');return;}f.image_url=result.publicUrl;imagePath=result.path;}for(const key of ['responsibilities','requirements','benefits','eligible_degrees','eligible_branches'])f[key]=String(f[key]||'').split('\n').map(x=>x.trim()).filter(Boolean);for(const key of ['required_skills','preferred_skills'])f[key]=String(f[key]||'').split(',').map((x:string)=>x.trim()).filter(Boolean);f.freshers_eligible=f.freshers_eligible==='on';f.certificate_eligible=f.certificate_eligible==='on';f.application_deadline=f.application_deadline||null;for(const key of ['positions','vacancy_count','salary_min','salary_max'])f[key]=f[key]?Number(f[key]):null;const r=await fetch('/api/admin/opportunities',{method:'PATCH',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({id:row.id,...f})}),d=await r.json();if(!r.ok){setMessage(d.error);if(imagePath)await fetch('/api/admin/job-image',{method:'DELETE',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({path:imagePath})});return;}if(row.image_url&&row.image_url!==f.image_url){try{const oldUrl=new URL(row.image_url),marker='/storage/v1/object/public/job-images/',at=oldUrl.pathname.indexOf(marker);if(at>=0){const oldPath=oldUrl.pathname.slice(at+marker.length);await fetch('/api/admin/job-image',{method:'DELETE',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({path:oldPath})})}}catch{}}onSaved();}return <form className="card" onSubmit={submit}><h2>Edit {row.title}</h2><p className="status">Job ID: {row.job_id||row.id.slice(0,8).toUpperCase()}</p><div className="formgrid"><EditInput label="Title" name="title" value={row.title} required/><div className="field"><label>Opportunity type</label><select name="kind" defaultValue={row.kind}><option value="job">Paid employment</option><option value="internship">Internship</option><option value="contributor">Contributor</option></select></div><EditInput label="Department" name="department" value={row.department} required/><EditInput label="Job category" name="job_category" value={row.job_category}/><EditInput label="Employment type" name="employment_type" value={row.employment_type}/><EditInput label="Engagement type" name="engagement_type" value={row.engagement_type} required/><div className="field"><label>Work mode</label><select name="work_mode" defaultValue={row.work_mode}><option>Remote</option><option>Hybrid</option><option>On-site</option><option>Other</option></select></div><EditInput label="Experience level" name="experience_level" value={row.experience_level}/><EditInput label="Experience required" name="experience_required" value={row.experience_required}/><EditInput label="Duration" name="duration" value={row.duration}/><EditInput label="Location" name="location" value={row.location}/><EditInput label="Country" name="country" value={row.country}/><EditInput label="State / Province" name="state" value={row.state}/><EditInput label="City" name="city" value={row.city}/><EditInput label="Office location" name="office_location" value={row.office_location}/><EditInput label="Compensation" name="compensation" value={row.compensation}/><EditInput label="Minimum compensation" name="salary_min" type="number" value={row.salary_min}/><EditInput label="Maximum compensation" name="salary_max" type="number" value={row.salary_max}/><EditInput label="Currency" name="currency" value={row.currency}/><EditInput label="Compensation disclosure" name="compensation_disclosure" value={row.compensation_disclosure}/><EditInput label="Application deadline" name="application_deadline" type="date" value={row.application_deadline}/><EditInput label="Number of vacancies" name="positions" type="number" value={row.positions}/><EditInput label="Required qualification" name="qualifications" value={row.qualifications}/><EditText label="Eligible degrees (one per line)" name="eligible_degrees" value={(row.eligible_degrees||[]).join('\n')}/><EditText label="Eligible branches (one per line)" name="eligible_branches" value={(row.eligible_branches||[]).join('\n')}/><EditInput label="Graduation year" name="graduation_year" value={row.graduation_year}/><EditInput label="Preferred skills (comma separated)" name="preferred_skills" value={(row.preferred_skills||[]).join(', ')}/><EditInput label="Benefits (one per line)" name="benefits" value={(row.benefits||[]).join('\n')}/><EditInput label="Contact email" name="contact_email" type="email" value={row.contact_email}/><EditInput label="Application instructions" name="application_instructions" value={row.application_instructions}/><EditInput label="Job image URL (clear to remove)" name="image_url" value={row.image_url}/><JobImageField/><div className="field"><label><input type="checkbox" name="freshers_eligible" defaultChecked={row.freshers_eligible}/> Freshers eligible</label></div><EditText label="Job overview" name="description" value={row.description} required/><EditText label="Responsibilities (one per line)" name="responsibilities" value={(row.responsibilities||[]).join('\n')}/><EditText label="Requirements (one per line)" name="requirements" value={(row.requirements||[]).join('\n')}/><EditInput label="Skills (comma separated)" name="required_skills" value={(row.required_skills||[]).join(', ')}/><EditInput label="Eligibility" name="eligibility" value={row.eligibility}/><EditText label="Selection process" name="selection_process" value={row.selection_process}/><EditText label="Additional information" name="additional_information" value={row.additional_information}/><EditText label="Certificate criteria" name="certificate_criteria" value={row.certificate_criteria}/><EditInput label="Mentorship" name="mentorship" value={row.mentorship}/><div className="field"><label><input type="checkbox" name="certificate_eligible" defaultChecked={row.certificate_eligible}/> Certificate eligible</label></div></div>{message&&<p className="notice">{message}</p>}<button className="btn">Save changes</button><button type="button" className="btn secondary" style={{marginLeft:8}} onClick={onCancel}>Cancel</button></form>}
function EditInput({label,name,value,type='text',required=false}:{label:string,name:string,value:any,type?:string,required?:boolean}){return <div className="field"><label>{label}</label><input name={name} type={type} defaultValue={value||''} required={required}/></div>}
function EditText({label,name,value,required=false}:{label:string,name:string,value:string,required?:boolean}){return <div className="field span2"><label>{label}</label><textarea name={name} defaultValue={value||''} required={required}/></div>}
